// Generated by vibes-espmatter – the Matter controller's web API: list, pair, control and remove
// devices (only with the HTTP server).
#include "espm_matter_registry.h"
#include "espm_matter_web.h"

#include <cstring>
#include <esp_timer.h>

#include <esp_matter.h>
#include <esp_matter_controller_cluster_command.h>
#include <esp_matter_controller_pairing_command.h>

#include <app-common/zap-generated/cluster-objects.h>

using namespace esp_matter;
using namespace chip::app::Clusters;
using namespace matter_nodes;

static const char *network_str(uint8_t n)
{
    switch (n) {
    case NET_THREAD: return "thread";
    case NET_WIFI: return "wifi";
    case NET_ONNETWORK: return "on-network";
    default: return "unknown";
    }
}

static bool (*s_access)(const char *user, uint64_t node, uint16_t ep) = nullptr;

void mesp_matter_set_access(bool (*allows)(const char *user, uint64_t node, uint16_t ep))
{
    s_access = allows;
}

bool mesp_matter_allows(const mesp_session_t &session, uint64_t node, uint16_t ep)
{
    if (session.role == MESP_ROLE_ADMIN) return true;
    return session.role == MESP_ROLE_USER && s_access && s_access(session.user, node, ep);
}

static esp_err_t nodes_handler(httpd_req_t *req)
{
    // Users only get the endpoints the access rule gives them (mesp_matter_set_access).
    mesp_session_t session;
    if (!mesp_web_require(req, MESP_ROLE_USER, &session)) return ESP_OK;
    Json j;
    int64_t now = esp_timer_get_time();
    {
        NodesLock lock;
        j.obj().key("nodes").arr();
        for (size_t i = 0; i < s_node_count; i++) {
            const mesp_node_t &n = s_nodes[i];
            // Admins also see nodes whose endpoints are not read yet, so they can refresh or remove them.
            bool visible = session.role == MESP_ROLE_ADMIN;
            for (uint8_t e = 0; e < n.ep_count; e++) visible |= mesp_matter_allows(session, n.node_id, n.ep[e]);
            if (!visible) continue;
            j.obj();
            j.key("id").unum(n.node_id);
            j.key("name").str(n.name);
            j.key("vendor").str(n.vendor);
            j.key("product").str(n.product);
            j.key("vendorId").num(n.vendor_id);
            j.key("productId").num(n.product_id);
            j.key("network").str(network_str(n.network));
            j.key("tags").arr();
            for (const char *t = s_tags[i]; *t;) {
                const char *end = strchr(t, ',');
                size_t len = end ? end - t : strlen(t);
                if (len) j.str(std::string(t, len));
                t += len + (end ? 1 : 0);
            }
            j.end_arr();
            if (s_last_seen[i]) {
                j.key("lastSeen").num((now - s_last_seen[i]) / 1000000);
            } else {
                j.key("lastSeen").null();
            }
            const mesp_battery_t &bat = s_battery[i];
            if (bat.updated) {
                static const char *levels[] = {"ok", "warning", "critical"};
                j.key("battery").obj();
                if (bat.percent_x2 >= 0) j.key("percent").num(bat.percent_x2 / 2);
                if (bat.level >= 0) j.key("level").str(levels[bat.level]);
                j.key("age").num((now - bat.updated) / 1000000);
                j.end_obj();
            }
            const mesp_power_t &power = s_power[i];
            if (power.updated) {
                j.key("power").obj();
                j.key("mw").num(power.mw).key("endpoint").num(power.ep);
                j.key("age").num((now - power.updated) / 1000000);
                j.end_obj();
            }
            j.key("endpoints").arr();
            for (uint8_t e = 0; e < n.ep_count; e++) {
                if (!mesp_matter_allows(session, n.node_id, n.ep[e])) continue;
                const mesp_light_t &l = s_light[i][e];
                j.obj().key("id").num(n.ep[e]).key("deviceType").num(n.device_type[e]);
                if (l.on >= 0) j.key("on").boolean(l.on);
                if (l.level >= 0) j.key("level").num(l.level);
                if (l.ct >= 0) j.key("ctMireds").num(l.ct);
                if (l.ct_min > 0 && l.ct_max > l.ct_min) {
                    j.key("ctMinMireds").num(l.ct_min).key("ctMaxMireds").num(l.ct_max);
                }
                const mesp_measure_t &m = s_measure[i][e];
                if (m.temp_at) j.key("temperature").num(m.temp);
                if (m.humidity_at) j.key("humidity").num(m.humidity);
                if (m.temp_at || m.humidity_at) {
                    int64_t at = m.temp_at > m.humidity_at ? m.temp_at : m.humidity_at;
                    j.key("measuredAge").num((now - at) / 1000000);
                }
                if (s_switch_features[i][e]) j.key("switchFeatures").num(s_switch_features[i][e]);
                j.end_obj();
            }
            j.end_arr();
            j.end_obj();
        }
        j.end_arr();
        j.key("capacity").num(MESP_MAX_NODES);
        j.end_obj();
    }
    return mesp_web_send_json(req, j.out());
}

static esp_err_t pair_status_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    static const char *states[] = {"idle", "running", "success", "failed"};
    check_pair_timeout();
    Json j;
    j.obj();
    j.key("state").str(states[s_pair.state]);
    j.key("nodeId").unum(s_pair.node_id);
    j.key("error").str(s_pair.error);
    if (s_pair.state == PAIR_RUNNING) {
        j.key("elapsed").num((esp_timer_get_time() - s_pair.started) / 1000000);
    }
    j.end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t pair_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    std::string body, code, name, network;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    if (!mesp_web_param(body, "code", code) || code.empty()) {
        return mesp_web_send_error(req, "400 Bad Request", "missing setup code");
    }
    mesp_web_param(body, "name", name);
    if (!mesp_web_param(body, "network", network)) network = "thread";
    esp_err_t err = start_pairing(code.c_str(), name.c_str(), network.c_str());
    if (err != ESP_OK) {
        return mesp_web_send_error(req, "409 Conflict", s_pair.error[0] ? s_pair.error : esp_err_to_name(err));
    }
    Json j;
    j.obj().key("ok").boolean(true).key("nodeId").unum(s_pair.node_id).end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t node_action_handler(httpd_req_t *req)
{
    mesp_session_t session;
    if (!mesp_web_require(req, MESP_ROLE_USER, &session)) return ESP_OK;
    std::string body, id_str, action;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    uint64_t node_id;
    if (!mesp_web_param(body, "id", id_str) || !mesp_parse_u64(id_str, node_id)) {
        return mesp_web_send_error(req, "400 Bad Request", "missing node id");
    }
    mesp_web_param(body, "action", action);
    int idx;
    {
        NodesLock lock;
        idx = node_index(node_id);
    }
    if (idx < 0) return mesp_web_send_error(req, "404 Not Found", "unknown node");

    // Dashboard users may read the state of their lights and switch, dim or tint them – nothing else.
    if (session.role != MESP_ROLE_ADMIN) {
        std::string ep_str, cluster_str;
        uint64_t ep = 0, cluster = 0;
        bool allowed = false;
        if (action == "state") {
            NodesLock lock;
            for (uint8_t e = 0; e < s_nodes[idx].ep_count; e++) allowed |= mesp_matter_allows(session, node_id, s_nodes[idx].ep[e]);
        } else if (action == "invoke" && mesp_web_param(body, "endpoint", ep_str) && mesp_parse_u64(ep_str, ep) &&
                   mesp_web_param(body, "cluster", cluster_str) && mesp_parse_u64(cluster_str, cluster)) {
            allowed = (cluster == OnOff::Id || cluster == LevelControl::Id || cluster == ColorControl::Id) &&
                      mesp_matter_allows(session, node_id, ep);
        }
        if (!allowed) return mesp_web_send_error(req, "403 Forbidden", "not allowed for this account");
    }

    esp_err_t err = ESP_OK;
    if (action == "rename") {
        std::string name;
        mesp_web_param(body, "name", name);
        // Blanks around the name are dropped.
        size_t a = name.find_first_not_of(" \t"), b = name.find_last_not_of(" \t");
        name = a == std::string::npos ? "" : name.substr(a, b - a + 1);
        NodesLock lock;
        notify_values(idx, false);
        copy_str(s_nodes[idx].name, sizeof(s_nodes[idx].name), name.c_str(), name.size());
        nodes_save();
        notify_values(idx, true);
    } else if (action == "tag") {
        // Comma-separated; blanks around, empty and repeated tags are dropped.
        std::string tags, clean;
        mesp_web_param(body, "tags", tags);
        for (size_t start = 0; start <= tags.size();) {
            size_t end = tags.find(',', start);
            if (end == std::string::npos) end = tags.size();
            size_t a = tags.find_first_not_of(' ', start), b = tags.find_last_not_of(' ', end - 1);
            if (a < end && b != std::string::npos && b >= a) {
                std::string tag = tags.substr(a, b - a + 1);
                if (("," + clean + ",").find("," + tag + ",") == std::string::npos) {
                    if (!clean.empty()) clean += ',';
                    clean += tag;
                }
            }
            start = end + 1;
        }
        if (clean.size() >= sizeof(s_tags[0])) {
            return mesp_web_send_error(req, "400 Bad Request", "tags too long");
        }
        NodesLock lock;
        strlcpy(s_tags[idx], clean.c_str(), sizeof(s_tags[idx]));
        nodes_save();
    } else if (action == "refresh") {
        esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
        err = read_node_info(node_id);
    } else if (action == "state") {
        esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
        err = read_node_state(node_id);
    } else if (action == "remove" || action == "forget") {
        if (action == "remove") {
            // Ask the device to leave our fabric; ignore failures for unreachable devices.
            esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
            controller::unpair_device(node_id);
        }
        node_remove(idx);
    } else if (action == "invoke") {
        std::string ep, cluster, command, data;
        mesp_web_param(body, "endpoint", ep);
        mesp_web_param(body, "cluster", cluster);
        mesp_web_param(body, "command", command);
        mesp_web_param(body, "data", data);
        uint64_t ep_id, cluster_id, command_id;
        if (!mesp_parse_u64(ep, ep_id) || !mesp_parse_u64(cluster, cluster_id) || !mesp_parse_u64(command, command_id)) {
            return mesp_web_send_error(req, "400 Bad Request", "endpoint, cluster and command are required");
        }
        esp_matter::lock::ScopedChipStackLock chip_lock(portMAX_DELAY);
        err = controller::send_invoke_cluster_command(node_id, ep_id, cluster_id, command_id,
                                                      data.empty() ? nullptr : data.c_str());
        if (err == ESP_OK) {
            NodesLock lock;
            s_last_seen[idx] = esp_timer_get_time();
        }
    } else {
        return mesp_web_send_error(req, "400 Bad Request", "unknown action");
    }
    if (err != ESP_OK) {
        return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
    }
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_matter_register_web()
{
    mesp_matter_access_init();
    mesp_matter_access_register_web();
    mesp_web_add("/api/matter/nodes", HTTP_GET, nodes_handler);
    mesp_web_add("/api/matter/pair", HTTP_GET, pair_status_handler);
    mesp_web_add("/api/matter/pair", HTTP_POST, pair_handler);
    mesp_web_add("/api/matter/node", HTTP_POST, node_action_handler);
}
